/**
 * Drawn stand-ins for Stimulus Pool assets.
 *
 * In production every image is generated by the fal image model from the
 * template's `elicitation_cues` and the Life Path theme, and generated *again*
 * next time — reviewing a competency "in a new context" means a new picture,
 * which is the whole reason the pool exists. These scenes exist so the
 * component layer, the layout and the demo can be built and reviewed before
 * that pipeline does.
 *
 * They are drawn rather than photographed for one reason beyond cost: a
 * describable picture needs unambiguous, nameable objects. A photograph is
 * full of things an A2 learner has no word for, and the evaluator would score
 * the omission as a vocabulary gap.
 *
 * Each scene names what it contains, because that list is the ceiling on what
 * the learner can be expected to say.
 */

import { type SceneId } from "./scene-ids";

export { sceneIds, type SceneId } from "./scene-ids";

export interface Scene {
  id: SceneId;
  /** For screen readers, and for the evaluator's expected-vocabulary set. */
  description: string;
  render: () => React.ReactNode;
}

const VIEWBOX = "0 0 400 260";

/** Shared defs — every scene draws on the same sky, ground and light. */
function Defs({ prefix }: { prefix: string }) {
  return (
    <defs>
      <linearGradient id={`${prefix}-sky`} x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor="oklch(0.94 0.035 232)" />
        <stop offset="100%" stopColor="oklch(0.985 0.012 300)" />
      </linearGradient>
      <linearGradient id={`${prefix}-ground`} x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor="oklch(0.9 0.03 150)" />
        <stop offset="100%" stopColor="oklch(0.84 0.045 150)" />
      </linearGradient>
      <linearGradient id={`${prefix}-wall`} x1="0" y1="0" x2="1" y2="0">
        <stop offset="0%" stopColor="oklch(0.9 0.012 265)" />
        <stop offset="100%" stopColor="oklch(0.82 0.016 265)" />
      </linearGradient>
      <linearGradient id={`${prefix}-indoor`} x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor="oklch(0.95 0.014 70)" />
        <stop offset="100%" stopColor="oklch(0.89 0.022 60)" />
      </linearGradient>
    </defs>
  );
}

/** A person, seated or standing, in one call. */
function Person({
  x,
  y,
  skin,
  shirt,
  seated = false,
  scale = 1,
}: {
  x: number;
  y: number;
  skin: string;
  shirt: string;
  seated?: boolean;
  scale?: number;
}) {
  const torso = seated ? 30 : 50;
  return (
    <g transform={`translate(${x} ${y}) scale(${scale})`}>
      <circle cx="0" cy="0" r="10" fill={skin} />
      <path d={`M-10 ${torso}v-${torso - 4}a10 10 0 0 1 20 0v${torso}z`} fill={shirt} />
      <rect
        x="-9"
        y={torso - 2}
        width="18"
        height={seated ? 10 : 24}
        rx={seated ? 3 : 4}
        fill="oklch(0.42 0.04 265)"
      />
    </g>
  );
}

