/** The raw SVG for a scene, sized by its container. */
export function SceneSvg({ id, className }: { id: SceneId; className?: string }) {
  const scene = scenes[id];
  return (
    <svg viewBox={VIEWBOX} className={className} role="img" aria-label={scene.description}>
      {scene.render()}
    </svg>
  );
}
